 "content": "def transform(grid):
    """Fill between the sloping edges of downward-pointing outlines."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    # For each row, find diagonal-outline cells belonging to descending
    # sides, then fill the horizontal span between paired sides.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                continue
            # A point is on a downward-left/right edge when the same-colored
            # outline continues one step outward on the row below.
            if r + 1 < h:
                for dc in (-1, 1):
                    nc = c + dc
                    if 0 <= nc < w and grid[r + 1][nc] == grid[r][c]:
                        # Fill the interior at the next row, between this
                        # edge pixel and its counterpart edge pixel.
                        other = c - dc
                        if 0 <= other < w and grid[r + 1][other] == grid[r][c]:
                            lo, hi = sorted((nc, other))
                            for x in range(lo + 1, hi):
                                if out[r + 1][x] == 0:
                                    out[r + 1][x] = 2
    # More generally, locate paired outline pixels on each row and fill
    # only spans for which the rows show the repeated expanding triangle.
    for r in range(1, h):
        prev = [c for c in range(w) if grid[r - 1][c] != 0]
        cur = [c for c in range(w) if grid[r][c] != 0]
        for a in prev:
            for b in prev:
                if b <= a:
                    continue
                # Paired sides expanding downwards have endpoints shifted
                # outward by one at the current row.
                if a - 1 in cur and b + 1 in cur:
                    for c in range(a, b + 1):
                        if out[r][c] == 0:
                            out[r][c] = 2
    return out

