    """Fill the interiors of outlined isosceles triangles, either orientation."""
    out = [row[:] for row in grid]
    h = len(grid)
    if h == 0:
        return out
    w = len(grid[0])
    for apex_r in range(h):
        for apex_c in range(w):
            color = grid[apex_r][apex_c]
            if color == 0:
                continue
            for dr in (-1, 1):
                distance = 1
                while 0 <= apex_r + dr * distance < h:
                    r = apex_r + dr * distance
                    left, right = apex_c - distance, apex_c + distance
                    # The triangle's sides must both be present at this
                    # level; stop extending if either side is absent.
                    if not (0 <= left < w and 0 <= right < w):
                        break
                    if grid[r][left] != color or grid[r][right] != color:
                        break
                    for c in range(left + 1, right):
                        if out[r][c] == 0:
                            out[r][c] = 2
                    distance += 1
    return out

